const ee = require('@google/earthengine');
const privateKey = require('../auth_keys/test-project-473922-29f05d49bed7');

async function runAnalysis() {
  // 1. Geometry & Time Definitions
  const cincinnati = ee.Geometry.Point([-84.5120, 39.1031]);
  const tempBand = 'mean_2m_air_temperature';
  const scale = 1000; // Scale for reduceRegion, ERA5 resolution is ~27.8km

  // 2. Data Acquisition & Pre-computation
  const era5Monthly = ee.ImageCollection('ECMWF/ERA5/MONTHLY');

  // Period 1: Historical Februaries (2010-2017)
  const historicalFebs = era5Monthly
    .filterBounds(cincinnati)
    .filter(ee.Filter.calendarRange(2, 2, 'month'))
    .filter(ee.Filter.date('2010-01-01', '2017-12-31'))
    .select(tempBand);

  // Period 2: Target February (2018)
  const feb2018 = era5Monthly
    .filterBounds(cincinnati)
    .filter(ee.Filter.date('2018-02-01', '2018-02-28'))
    .select(tempBand);

  // 3. Data Availability Check
  const historicalCount = await historicalFebs.size().getInfo();
  const feb2018Count = await feb2018.size().getInfo();

  if (historicalCount === 0 || feb2018Count === 0) {
    console.log(`Historical Feb images (2010-2017): ${historicalCount}`);
    console.log(`Target Feb 2018 images: ${feb2018Count}`);
    console.log("Empty Collection: No images found for one or both periods.");
    console.log("C1");
    return;
  }
  console.log(`Historical Feb images (2010-2017): ${historicalCount}`);
  console.log(`Target Feb 2018 images: ${feb2018Count}`);

  // 4. Processing & Calculation
  // Find the maximum temperature during the historical period
  const maxHistoricalImage = historicalFebs.max(); // Get the single image with the max temp for each pixel over the years
  const maxHistoricalTempDict = await maxHistoricalImage.reduceRegion({
    reducer: ee.Reducer.mean(),
    geometry: cincinnati,
    scale: scale,
    maxPixels: 1e9
  }).getInfo();

  // Get the temperature for Feb 2018
  const feb2018Image = ee.Image(feb2018.first());
  const feb2018TempDict = await feb2018Image.reduceRegion({
    reducer: ee.Reducer.mean(),
    geometry: cincinnati,
    scale: scale,
    maxPixels: 1e9
  }).getInfo();

  // 5. Validation and Final Answer
  const maxHistoricalTempK = maxHistoricalTempDict[tempBand];
  const feb2018TempK = feb2018TempDict[tempBand];

  if (maxHistoricalTempK === null || feb2018TempK === null) {
      console.log("Calculation failed: could not retrieve temperature values.");
      console.log(`Historical Max Temp: ${maxHistoricalTempK}`);
      console.log(`Feb 2018 Temp: ${feb2018TempK}`);
      console.log("C3");
      return;
  }

  // Convert from Kelvin to Celsius for readability
  const maxHistoricalTempC = maxHistoricalTempK - 273.15;
  const feb2018TempC = feb2018TempK - 273.15;

  console.log(`Warmest Feb (2010-2017) Temp: ${maxHistoricalTempC.toFixed(2)} C`);
  console.log(`Feb 2018 Temp: ${feb2018TempC.toFixed(2)} C`);

  if (feb2018TempC > maxHistoricalTempC) {
    console.log("A");
  } else {
    console.log("B");
  }
}

async function initEE() {
  await new Promise((resolve, reject) => {
    ee.data.authenticateViaPrivateKey(privateKey, resolve, reject);
  });
  await new Promise((resolve, reject) => {
    ee.initialize(null, null, resolve, reject);
  });
  await runAnalysis();
}

initEE().catch(err => {
    console.error("An error occurred:", err.message);
    console.log("D");
});
